import * as THREE from './vendor/three.module.js';

/* ------------------------------------------------------------------ *
 * BELLINGHAM HEAT — a real-time 3D crime game
 * Three.js renderer, procedural city, driving, pursuit, missions.
 * ------------------------------------------------------------------ */

const canvas = document.getElementById('game');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.18;

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x071210);
scene.fog = new THREE.FogExp2(0x071210, 0.0019);

const camera = new THREE.PerspectiveCamera(58, innerWidth / innerHeight, 0.5, 4000);
camera.position.set(0, 20, 30);

addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75));
  renderer.setSize(innerWidth, innerHeight);
});

/* ----------------------------- helpers ---------------------------- */
let seed = 20261123;
function rnd() { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; }
const pick = (a) => a[Math.floor(rnd() * a.length)];
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const lerp = (a, b, t) => a + (b - a) * t;

const WORLD = 900;
const ROADS_X = [-615, -235, 145, 525];
const ROADS_Z = [-595, -205, 185, 575];
const BLOCK_X = [[-900, -660], [-570, -280], [-190, 100], [190, 480], [570, 900]];
const BLOCK_Z = [[-900, -640], [-550, -250], [-160, 140], [230, 530], [620, 900]];

const colliders = [];
const vehicles = [];
const policeCars = [];
const missionMarkers = [];
const flashLights = [];
const puddleMats = [];

const player = {
  pos: new THREE.Vector3(-615, 0, -250),
  heading: Math.PI,
  walk: 0,
  hp: 100,
  onFoot: true,
  car: null
};
let cash = 2450;
let wanted = 0;
let wantedTimer = 0;
let stage = 0;
let started = false;
let over = false;
let toastTimer = 0;
let clockTime = 0;

const keys = {};
addEventListener('keydown', (e) => {
  const k = e.key.toLowerCase();
  if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].includes(k)) e.preventDefault();
  if (!keys[k] && k === 'e') toggleVehicle();
  keys[k] = true;
});
addEventListener('keyup', (e) => { keys[e.key.toLowerCase()] = false; });
addEventListener('blur', () => { for (const k in keys) keys[k] = false; });

/* ------------------------------ lights ---------------------------- */
const hemi = new THREE.HemisphereLight(0x6c94a8, 0x1a2018, 0.75);
scene.add(hemi);

const moon = new THREE.DirectionalLight(0xa8c8ff, 1.45);
moon.position.set(-260, 380, -160);
moon.castShadow = true;
moon.shadow.mapSize.set(2048, 2048);
moon.shadow.camera.left = -520;
moon.shadow.camera.right = 520;
moon.shadow.camera.top = 520;
moon.shadow.camera.bottom = -520;
moon.shadow.camera.far = 1200;
moon.shadow.bias = -0.0004;
scene.add(moon);
scene.add(moon.target);

const fill = new THREE.DirectionalLight(0xff8866, 0.35);
fill.position.set(300, 120, 300);
scene.add(fill);

/* ---------------------------- materials --------------------------- */
const MAT = {
  asphalt: new THREE.MeshStandardMaterial({ color: 0x20282a, roughness: 0.34, metalness: 0.5 }),
  sidewalk: new THREE.MeshStandardMaterial({ color: 0x3a4744, roughness: 0.9 }),
  curb: new THREE.MeshStandardMaterial({ color: 0x66736d, roughness: 0.8 }),
  roof: new THREE.MeshStandardMaterial({ color: 0x1d2422, roughness: 0.85 }),
  metal: new THREE.MeshStandardMaterial({ color: 0x39433f, roughness: 0.55, metalness: 0.65 }),
  trunk: new THREE.MeshStandardMaterial({ color: 0x3a2c22, roughness: 1 }),
  leaf: new THREE.MeshStandardMaterial({ color: 0x1d4a37, roughness: 1 }),
  glass: new THREE.MeshStandardMaterial({ color: 0x0b1b20, roughness: 0.12, metalness: 0.9 }),
  water: new THREE.MeshStandardMaterial({ color: 0x0a2531, roughness: 0.18, metalness: 0.85 }),
  white: new THREE.MeshStandardMaterial({ color: 0xdfe9e4, roughness: 0.6 })
};

/* --------------------------- base world --------------------------- */
const ground = new THREE.Mesh(new THREE.PlaneGeometry(1900, 1900), MAT.asphalt);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

const water = new THREE.Mesh(new THREE.PlaneGeometry(7000, 7000), MAT.water);
water.rotation.x = -Math.PI / 2;
water.position.y = -1.4;
scene.add(water);

// road strips
for (const x of ROADS_X) {
  const r = new THREE.Mesh(new THREE.PlaneGeometry(90, 1800), new THREE.MeshStandardMaterial({ color: 0x262f31, roughness: 0.28, metalness: 0.55 }));
  r.rotation.x = -Math.PI / 2; r.position.set(x, 0.012, 0); r.receiveShadow = true; scene.add(r);
}
for (const z of ROADS_Z) {
  const r = new THREE.Mesh(new THREE.PlaneGeometry(1800, 90), new THREE.MeshStandardMaterial({ color: 0x262f31, roughness: 0.28, metalness: 0.55 }));
  r.rotation.x = -Math.PI / 2; r.position.set(0, 0.013, z); r.receiveShadow = true; scene.add(r);
}

// lane dashes (instanced)
{
  const dashGeo = new THREE.BoxGeometry(1.05, 0.04, 9);
  const dashMat = new THREE.MeshStandardMaterial({ color: 0xe6d59a, emissive: 0x776222, emissiveIntensity: 0.45, roughness: 0.6 });
  const count = 4 * 2 * 13 + 4 * 2 * 13;
  const inst = new THREE.InstancedMesh(dashGeo, dashMat, count);
  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const qy = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), Math.PI / 2);
  const s = new THREE.Vector3(1, 1, 1);
  let i = 0;
  for (const x of ROADS_X) for (let z = -790; z <= 790; z += 128) {
    m.compose(new THREE.Vector3(x, 0.04, z), q, s); inst.setMatrixAt(i++, m);
  }
  for (const z of ROADS_Z) for (let x = -790; x <= 790; x += 128) {
    m.compose(new THREE.Vector3(x, 0.04, z), qy, s); inst.setMatrixAt(i++, m);
  }
  inst.count = i;
  inst.receiveShadow = true;
  scene.add(inst);
}

// crosswalk stripes
{
  const geo = new THREE.BoxGeometry(7, 0.03, 2.2);
  const mat = new THREE.MeshStandardMaterial({ color: 0xd6e2da, roughness: 0.7 });
  for (const x of ROADS_X) for (const z of ROADS_Z) for (let k = -3; k <= 3; k++) {
    const a = new THREE.Mesh(geo, mat); a.position.set(x + k * 10, 0.035, z + 48); scene.add(a);
    const b = new THREE.Mesh(geo, mat); b.position.set(x + k * 10, 0.035, z - 48); scene.add(b);
  }
}

/* ------------------------- city buildings ------------------------- */
function makeFacadeTexture() {
  const c = document.createElement('canvas');
  c.width = 128; c.height = 256;
  const g = c.getContext('2d');
  const walls = ['#5a6157', '#6b6255', '#4e5c58', '#73675b', '#56605d'];
  g.fillStyle = pick(walls); g.fillRect(0, 0, 128, 256);
  for (let y = 10; y < 250; y += 30) {
    for (let x = 10; x < 120; x += 30) {
      const lit = rnd() < 0.42;
      g.fillStyle = lit ? pick(['#ffd48a', '#ffe9b0', '#9fd4e0', '#ffb46e']) : '#10191a';
      g.fillRect(x, y, 17, 15);
      if (lit) { g.globalAlpha = 0.28; g.fillRect(x - 3, y - 3, 23, 21); g.globalAlpha = 1; }
    }
    g.fillStyle = '#00000022'; g.fillRect(0, y + 22, 128, 2);
  }
  g.fillStyle = '#ffffff10'; g.fillRect(0, 0, 4, 256);
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}
const facadeBases = [makeFacadeTexture(), makeFacadeTexture(), makeFacadeTexture(), makeFacadeTexture()];

function neonTexture(text, color) {
  const c = document.createElement('canvas'); c.width = 512; c.height = 128;
  const g = c.getContext('2d');
  g.fillStyle = '#070d0c'; g.fillRect(0, 0, 512, 128);
  g.strokeStyle = color; g.lineWidth = 6; g.strokeRect(8, 8, 496, 112);
  g.font = 'italic 900 70px Impact, Arial';
  g.textAlign = 'center'; g.textBaseline = 'middle';
  g.shadowColor = color; g.shadowBlur = 28;
  g.fillStyle = color; g.fillText(text, 256, 68);
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

const glowCanvas = document.createElement('canvas');
glowCanvas.width = glowCanvas.height = 128;
{
  const g = glowCanvas.getContext('2d');
  const gr = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  gr.addColorStop(0, 'rgba(255,240,205,1)');
  gr.addColorStop(0.25, 'rgba(255,214,150,.55)');
  gr.addColorStop(1, 'rgba(255,190,110,0)');
  g.fillStyle = gr; g.fillRect(0, 0, 128, 128);
}
const glowTex = new THREE.CanvasTexture(glowCanvas);

const signs = ['BAY CITY', 'MOTEL', 'NOODLES', 'DOCK 7', 'PAWN', 'RAIL & ALE', 'SEAMART'];
const signColors = ['#ff5f4a', '#59c7d8', '#ffcf5c', '#ff5fa2', '#7ef0a0'];
const neonMats = [];

function addBuilding(x, z, w, d, h) {
  const base = pick(facadeBases);
  const tx = base.clone(); tx.needsUpdate = true; tx.repeat.set(Math.max(1, Math.round(d / 9)), Math.max(1, Math.round(h / 8)));
  const tz = base.clone(); tz.needsUpdate = true; tz.repeat.set(Math.max(1, Math.round(w / 9)), Math.max(1, Math.round(h / 8)));
  const mx = new THREE.MeshStandardMaterial({ map: tx, emissiveMap: tx, emissive: 0xffcf8f, emissiveIntensity: 0.42, roughness: 0.78 });
  const mz = new THREE.MeshStandardMaterial({ map: tz, emissiveMap: tz, emissive: 0xffcf8f, emissiveIntensity: 0.42, roughness: 0.78 });
  const geo = new THREE.BoxGeometry(w, h, d);
  const mesh = new THREE.Mesh(geo, [mx, mx, MAT.roof, MAT.roof, mz, mz]);
  mesh.position.set(x, h / 2 + 0.18, z);
  mesh.castShadow = true; mesh.receiveShadow = true;
  scene.add(mesh);
  colliders.push({ x0: x - w / 2, x1: x + w / 2, z0: z - d / 2, z1: z + d / 2 });

  if (h > 42) {
    const top = new THREE.Mesh(new THREE.BoxGeometry(w * 0.35, 4, d * 0.35), MAT.roof);
    top.position.set(x + (rnd() - 0.5) * w * 0.3, h + 2.2, z + (rnd() - 0.5) * d * 0.3);
    top.castShadow = true; scene.add(top);
    if (rnd() < 0.5) {
      const ant = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.15, 12, 5), MAT.metal);
      ant.position.set(x, h + 8, z); scene.add(ant);
      const tip = new THREE.Mesh(new THREE.SphereGeometry(0.4, 6, 6), new THREE.MeshBasicMaterial({ color: 0xff3344 }));
      tip.position.set(x, h + 14, z); scene.add(tip);
    }
  }

  if (rnd() < 0.55) {
    const color = pick(signColors);
    const t = neonTexture(pick(signs), color);
    const sw = Math.min(w * 0.8, 14);
    const sign = new THREE.Mesh(new THREE.PlaneGeometry(sw, sw / 4), new THREE.MeshBasicMaterial({ map: t, transparent: true, side: THREE.DoubleSide }));
    const face = rnd() < 0.5;
    sign.position.set(face ? x + w / 2 + 0.3 : x, 4.8 + rnd() * Math.min(18, h * 0.5), face ? z : z + d / 2 + 0.3);
    sign.rotation.y = face ? -Math.PI / 2 : 0;
    scene.add(sign);
    neonMats.push(sign.material);
  }
}

function addTree(x, z, s = 1) {
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.32 * s, 0.45 * s, 2.6 * s, 6), MAT.trunk);
  trunk.position.set(x, 1.3 * s, z); trunk.castShadow = true; scene.add(trunk);
  for (let i = 0; i < 3; i++) {
    const cone = new THREE.Mesh(new THREE.ConeGeometry((2.5 - i * 0.55) * s, (4 - i * 0.5) * s, 7), MAT.leaf);
    cone.position.set(x, (2.6 + i * 1.75) * s, z); cone.castShadow = true; scene.add(cone);
  }
}

let buildingCount = 0;
BLOCK_X.forEach((bx, ix) => {
  BLOCK_Z.forEach((bz, iz) => {
    const w = bx[1] - bx[0], d = bz[1] - bz[0];
    const cx = (bx[0] + bx[1]) / 2, cz = (bz[0] + bz[1]) / 2;
    const pad = 10;
    const walk = new THREE.Mesh(new THREE.BoxGeometry(w, 0.36, d), MAT.sidewalk);
    walk.position.set(cx, 0.18, cz); walk.receiveShadow = true; scene.add(walk);
    const curb = new THREE.Mesh(new THREE.BoxGeometry(w + 5, 0.22, d + 5), MAT.curb);
    curb.position.set(cx, 0.06, cz); curb.receiveShadow = true; scene.add(curb);

    const cols = w > 270 ? 2 : 1;
    const innerW = w - pad * 2, innerD = d - pad * 2;
    const slotW = innerW / cols;
    for (let k = 0; k < cols; k++) {
      const bw = slotW * (cols === 1 ? (0.62 + rnd() * 0.2) : (0.72 + rnd() * 0.16));
      const bd = innerD * (0.6 + rnd() * 0.26);
      const edge = ix === 0 || ix === 4 || iz === 0 || iz === 4;
      const h = 16 + rnd() * (edge ? 44 : 78);
      const bxc = bx[0] + pad + slotW * (k + 0.5) + (rnd() - 0.5) * 6;
      const bzc = cz + (rnd() - 0.5) * (innerD - bd - 6) * 0.5;
      addBuilding(bxc, bzc, bw, bd, h);
      buildingCount++;
    }
    if (rnd() < 0.5) addTree(bx[0] + 12, bz[0] + 12, 0.85 + rnd() * 0.4);
    if (rnd() < 0.5) addTree(bx[1] - 12, bz[1] - 12, 0.85 + rnd() * 0.4);
  });
});

/* --------------------------- street lights ------------------------ */
const lampGeo = new THREE.CylinderGeometry(0.13, 0.18, 8, 6);
const lampHeadGeo = new THREE.SphereGeometry(0.42, 8, 8);
const lampMat = new THREE.MeshStandardMaterial({ color: 0x2b3434, roughness: 0.5, metalness: 0.7 });
const lampGlowMat = new THREE.MeshBasicMaterial({ color: 0xffe0a0 });
const coneMat = new THREE.MeshBasicMaterial({ color: 0xffcf8a, transparent: true, opacity: 0.035, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
const coneGeo = new THREE.ConeGeometry(5, 8, 10, 1, true);
let lampCount = 0;
function addLamp(x, z) {
  const pole = new THREE.Mesh(lampGeo, lampMat); pole.position.set(x, 4, z); scene.add(pole);
  const head = new THREE.Mesh(lampHeadGeo, lampGlowMat); head.position.set(x, 8.05, z); scene.add(head);
  const spr = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex, color: 0xffd7a0, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false }));
  spr.position.set(x, 8.05, z); spr.scale.set(11, 11, 1); scene.add(spr);
  const cone = new THREE.Mesh(coneGeo, coneMat); cone.position.set(x, 4, z); scene.add(cone);
  lampCount++;
}
for (const x of ROADS_X) for (const z of ROADS_Z) {
  addLamp(x - 58, z - 58); addLamp(x + 58, z + 58);
}
for (const x of ROADS_X) {
  addLamp(x - 60, -800); addLamp(x + 60, 800);
}
for (const z of ROADS_Z) {
  addLamp(-800, z + 60); addLamp(800, z - 60);
}

/* --------------------------- puddles ------------------------------ */
{
  const pgeo = new THREE.PlaneGeometry(18, 7);
  for (let i = 0; i < 26; i++) {
    const mat = new THREE.MeshStandardMaterial({
      color: pick([0x18343a, 0x2e1f33, 0x1d3330]),
      transparent: true, opacity: 0.65, roughness: 0.06, metalness: 0.95,
      emissive: pick([0x0d3540, 0x2b1026, 0x0e2b29]), emissiveIntensity: 0.7
    });
    const p = new THREE.Mesh(pgeo, mat);
    const onX = rnd() < 0.5;
    if (onX) p.position.set(pick(ROADS_X) + (rnd() - 0.5) * 55, 0.025, (rnd() - 0.5) * 1700);
    else p.position.set((rnd() - 0.5) * 1700, 0.025, pick(ROADS_Z) + (rnd() - 0.5) * 55);
    p.rotation.x = -Math.PI / 2;
    p.scale.set(0.6 + rnd() * 1.5, 0.5 + rnd(), 1);
    p.receiveShadow = true;
    scene.add(p); puddleMats.push(mat);
  }
  const reflGeo = new THREE.PlaneGeometry(26, 2.4);
  for (let i = 0; i < 18; i++) {
    const m = new THREE.MeshBasicMaterial({ color: pick([0xff5f4a, 0x59c7d8, 0xffcf5c]), transparent: true, opacity: 0.09, blending: THREE.AdditiveBlending, depthWrite: false });
    const r = new THREE.Mesh(reflGeo, m);
    r.rotation.x = -Math.PI / 2;
    r.position.set(pick(ROADS_X) + (rnd() - 0.5) * 45, 0.03, (rnd() - 0.5) * 1600);
    scene.add(r);
  }
}

/* ------------------------ mountains / skyline -------------------- */
{
  const mMat = new THREE.MeshStandardMaterial({ color: 0x122522, roughness: 1 });
  for (let i = 0; i < 26; i++) {
    const a = (i / 26) * Math.PI * 2;
    const rad = 1500 + rnd() * 420;
    const h = 160 + rnd() * 360;
    const cone = new THREE.Mesh(new THREE.ConeGeometry(240 + rnd() * 220, h, 5), mMat);
    cone.position.set(Math.cos(a) * rad, h / 2 - 8, Math.sin(a) * rad);
    cone.rotation.y = rnd() * Math.PI;
    scene.add(cone);
  }
  // distant waterfront cranes
  const craneMat = new THREE.MeshStandardMaterial({ color: 0x1b2626, roughness: 0.8 });
  for (let i = 0; i < 4; i++) {
    const g = new THREE.Group();
    const leg1 = new THREE.Mesh(new THREE.BoxGeometry(2, 40, 2), craneMat); leg1.position.set(-8, 20, 0);
    const leg2 = leg1.clone(); leg2.position.x = 8;
    const beam = new THREE.Mesh(new THREE.BoxGeometry(46, 2, 3), craneMat); beam.position.y = 40;
    g.add(leg1, leg2, beam);
    g.position.set(950 + i * 90, 0, -500 + i * 260);
    g.rotation.y = -0.4;
    scene.add(g);
  }
}

/* ----------------------------- vehicles --------------------------- */
const carGeoCache = {
  body: new THREE.BoxGeometry(1.95, 0.62, 4.3),
  cabin: new THREE.BoxGeometry(1.62, 0.52, 1.95),
  wheel: new THREE.CylinderGeometry(0.36, 0.36, 0.26, 12),
  light: new THREE.BoxGeometry(0.42, 0.18, 0.1),
  bumper: new THREE.BoxGeometry(1.9, 0.22, 0.24)
};
const wheelMat = new THREE.MeshStandardMaterial({ color: 0x090b0b, roughness: 0.85 });
const headlightMat = new THREE.MeshBasicMaterial({ color: 0xfff1c0 });
const taillightMat = new THREE.MeshBasicMaterial({ color: 0xff2b2b });
const copRed = new THREE.MeshBasicMaterial({ color: 0xff1e3a });
const copBlue = new THREE.MeshBasicMaterial({ color: 0x2b6bff });

function makeCar(color, cop = false) {
  const g = new THREE.Group();
  const paint = new THREE.MeshStandardMaterial({ color, roughness: 0.28, metalness: 0.72 });
  const body = new THREE.Mesh(carGeoCache.body, paint);
  body.position.y = 0.68; body.castShadow = true; body.receiveShadow = true; g.add(body);
  const hood = new THREE.Mesh(new THREE.BoxGeometry(1.82, 0.2, 1.25), paint);
  hood.position.set(0, 0.92, 1.42); hood.castShadow = true; g.add(hood);
  const cabin = new THREE.Mesh(carGeoCache.cabin, MAT.glass);
  cabin.position.set(0, 1.2, -0.22); cabin.castShadow = true; g.add(cabin);
  for (const sx of [-1, 1]) for (const sz of [-1.35, 1.35]) {
    const w = new THREE.Mesh(carGeoCache.wheel, wheelMat);
    w.rotation.z = Math.PI / 2;
    w.position.set(sx * 1.02, 0.38, sz);
    w.castShadow = true; g.add(w);
  }
  for (const sx of [-1, 1]) {
    const hl = new THREE.Mesh(carGeoCache.light, headlightMat);
    hl.position.set(sx * 0.6, 0.78, 2.16); g.add(hl);
    const tl = new THREE.Mesh(carGeoCache.light, taillightMat);
    tl.position.set(sx * 0.6, 0.8, -2.16); g.add(tl);
  }
  const fb = new THREE.Mesh(carGeoCache.bumper, new THREE.MeshStandardMaterial({ color: 0x181d1d, metalness: 0.6, roughness: 0.5 }));
  fb.position.set(0, 0.44, 2.18); g.add(fb);
  const rb = fb.clone(); rb.position.z = -2.18; g.add(rb);

  if (cop) {
    const bar = new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.16, 0.36), MAT.metal);
    bar.position.set(0, 1.53, -0.2); g.add(bar);
    const red = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.16, 0.34), copRed.clone());
    red.position.set(-0.42, 1.66, -0.2); g.add(red);
    const blue = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.16, 0.34), copBlue.clone());
    blue.position.set(0.42, 1.66, -0.2); g.add(blue);
    flashLights.push({ red, blue, phase: rnd() * 6 });
    const stripe = new THREE.Mesh(new THREE.BoxGeometry(1.98, 0.3, 2.6), new THREE.MeshStandardMaterial({ color: 0xe8eef0, roughness: 0.5 }));
    stripe.position.set(0, 0.62, 0.2); g.add(stripe);
  }
  scene.add(g);
  return g;
}

function addHeadlights(group) {
  const spot = new THREE.SpotLight(0xffe2b0, 55, 55, 0.48, 0.55, 1.4);
  spot.position.set(0, 0.9, 2.2);
  spot.target.position.set(0, 0.2, 22);
  group.add(spot, spot.target);
  const spr = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex, color: 0xffe8b8, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending, depthWrite: false }));
  spr.position.set(0, 0.8, 3.2); spr.scale.set(12, 5, 1); group.add(spr);
}

function spawnTraffic() {
  const palette = [0xc84e3e, 0xb9a363, 0x5f7c86, 0xd5cfba, 0x7c4f72, 0x3f6f5c];
  for (let i = 0; i < 16; i++) {
    const vertical = i % 2 === 0;
    const color = pick(palette);
    const mesh = makeCar(color);
    const road = vertical ? pick(ROADS_X) : pick(ROADS_Z);
    const dir = rnd() < 0.5 ? 1 : -1;
    const lane = road + dir * 20;
    const pos = new THREE.Vector3(
      vertical ? lane : (rnd() - 0.5) * 1600,
      0,
      vertical ? (rnd() - 0.5) * 1600 : lane
    );
