for (let i...) { const d=rainDrops[i]; d.y -= d.speed*dt; if(d.y<0){d.y=55; d.x=...; d.z=...} const k=i*6; arr[k]=d.x; arr[k+1]=d.y; arr[k+2]=d.z; arr[k+3]=d.x; arr[k+4]=d.y+d.len; arr[k+5]=d.z; }
