function makeFacadeTexture() {
  const c = document.createElement('canvas');
  c.width = 128; c.height = 256;
  const g = c.getContext('2d');
  const walls = ['#485049', '#554d43', '#3f4c49', '#5a5148', '#444e4b'];
  g.fillStyle = pick(walls); g.fillRect(0, 0, 128, 256);
  for (let y = 18; y < 246; y += 42) {
    for (let x = 12; x < 118; x += 38) {
      const lit = rnd() < 0.36;
      g.fillStyle = lit ? pick(['#e8c37d', '#f0dca4', '#8ec1cb', '#e2a768']) : '#0d1415';
      g.fillRect(x, y, 23, 22);
      if (lit) { g.globalAlpha = 0.22; g.fillRect(x - 4, y - 4, 31, 30); g.globalAlpha = 1; }
    }
    g.fillStyle = '#00000022'; g.fillRect(0, y + 30, 128, 3);
  }
  g.fillStyle = '#ffffff0d'; g.fillRect(0, 0, 5, 256);
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}

