959: /* --------------------------- collisions -------------------------- */
960: function resolveCollision(obj, radius) {
961:   const p = obj.pos;
962:   for (const c of colliders) {
963:     const cx = clamp(p.x, c.x0, c.x1);
964:     const cz = clamp(p.z, c.z0, c.z1);
965:     let dx = p.x - cx, dz = p.z - cz;
966:     let d = Math.hypot(dx, dz);
967:     if (d < radius) {
968:       if (d < 0.001) {
969:         // inside the box, push toward the nearest edge
970:         const left = Math.abs(p.x - c.x0), right = Math.abs(c.x1 - p.x);
971:         const back = Math.abs(p.z - c.z0), front = Math.abs(c.z1 - p.z);
972:         const m = Math.min(left, right, back, front);
973:         if (m === left) p.x = c.x0 - radius;
974:         else if (m === right) p.x = c.x1 + radius;
975:         else if (m === back) p.z = c.z0 - radius;
976:         else p.z = c.z1 + radius;
977:       } else {
978:         const push = (radius - d) / d;
979:         p.x += dx * push; p.z += dz * push;
980:       }
981:       obj.speed = Math.min(obj.speed || 0, 4);
982:       obj.hit = true;
983:     }
984:   }
985:   p.x = clamp(p.x, -890, 890);
986:   p.z = clamp(p.z, -890, 890);
987: }
