```glsl
uniform sampler2D tScene, tBloomA, tBloomB;
uniform vec2 uResolution;
uniform float uTime, uExposure, uBloom, uVignette, uGrain;
varying vec2 vUv;

const mat3 ACESIn = mat3(vec3(0.59719,0.07600,0.02840), vec3(0.35458,0.90834,0.13383), vec3(0.04823,0.01566,0.83777));
const mat3 ACESOut = mat3(vec3(1.60475,-0.10208,-0.00327), vec3(-0.53108,1.10813,-0.07276), vec3(-0.07367,-0.00605,1.07602));
vec3 rrt(vec3 v){ vec3 a = v*(v+0.0245786)-0.000090537; vec3 b = v*(0.983729*v+0.4329510)+0.238081; return a/b; }
vec3 aces(vec3 c){ c = ACESIn*c; c = rrt(c); c = ACESOut*c; return clamp(c,0.0,1.0); }
float hash(vec2 p){ return fract(sin(dot(p, vec2(12.9898,78.233)))*43758.5453); }

void main(){
  vec2 uv = vUv;
  vec2 d = uv - 0.5;
  float r2 = dot(d, d);
  // subtle lateral chromatic aberration toward the frame edge
  vec2 ca = d * 0.0022 * r2 * 4.0;
  vec3 col;
  col.r = texture2D(tScene, uv - ca).r;
  col.g = texture2D(tScene, uv).g;
  col.b = texture2D(tScene, uv + ca).b;

  vec3 bloom = texture2D(tBloomA, uv).rgb * 0.65 + texture2D(tBloomB, uv).rgb * 0.85;
  col += bloom * uBloom;
  col *= uExposure;
  col = aces(col);

  // grade: cool shadows, warm highlights, gentle saturation
  float luma = dot(col, vec3(0.2126, 0.7152, 0.0722));
  col = mix(col, col * vec3(0.93, 1.01, 1.09), 0.55 * (1.0 - luma));
  col = mix(col, col * vec3(1.06, 1.01, 0.95), 0.35 * luma);
  col = mix(vec3(luma), col, 1.08);

  // vignette + grain
  col *= 1.0 - uVignette * smoothstep(0.15, 0.85, r2 * 1.9);
  float n = hash(uv * uResolution + fract(uTime) * 91.7) - 0.5;
  col += n * uGrain;

  gl_FragColor = vec4(max(col, 0.0), 1.0);
}
```

